def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be , or .

    Args:
        a (int or str): The first value to compare
        b (int or str): The second value to compare

    Returns:
        int or str: The larger value in the same type as the input, or None if equal
    """
    # Try to convert both inputs to float
    try:
        a_as_float = float(a)
        b_as_float = float(b)
    # If either input can't be converted to float, assume it's a string and try to parse it
    except ValueError:
        try:
            a_as_float = float(a.replace(',', '.'))
            b_as_float = float(b.replace(',', '.'))
        # If both inputs are strings but can't be converted to float
        except ValueError:
            # If they're already successfully converted, return the larger string
            if a_as_float > b_as_float:
                return a
            elif a_as_float < b_as_float:
                return b
            # If equal
            else:
                return None
        # If only one of the inputs is a string and can't be converted to float
        else:
            # Return the larger string
            if a_as_float > b_as_float:
                return a
            elif a_as_float < b_as_float:
                return b
            # If equal
            else:
                return None
    # If both inputs are floats, return the larger one
    else:
        if a_as_float > b_as_float:
            return a_as_float
        elif a_as_float < b_as_float:
            return b_as_float
        # If equal
        else:
            return None
